import { encodedLiteral, projectionFile } from "../rendering.js";
import { kebabCase } from "./naming.js";
import { sha256 } from "../../../primitives/sha256.js";
function renderObject(typeName, definition) {
    const dependencies = new Set(definition.fields.flatMap((field) => field.dependencies));
    dependencies.delete(typeName);
    const imports = [...dependencies].sort()
        .map((dependency) => `import type { ${dependency} } from "./${kebabCase(dependency)}.js";`)
        .join("\n");
    const constants = definition.constants
        .map((constant) => `export const ${constant.name} = ${encodedLiteral("node", constant.value)} as const;`)
        .join("\n");
    const fields = definition.fields
        .map((field) => `  ${field.name}${field.optional ? "?" : ""}: ${field.type};`)
        .join("\n");
    return [
        imports ? `${imports}\n\n` : "",
        constants ? `${constants}\n\n` : "",
        `// Projected from kernel/schemas/${definition.sourcePointer.replace(/#$/, "").replace("#/properties/", "/properties/")}.\n`,
        "// GENERATED by tools/src/projection/providers/node/structural-projection-provider.ts — do not hand-edit.\n",
        `export interface ${typeName} {\n${fields}\n}\n`
    ].join("");
}
function renderDefinition(definition) {
    if (definition.kind === "enum") {
        return `// Projected from kernel/schemas/${definition.sourcePointer.replace(/#$/, "").replace("#/properties/", "/properties/")}.\n` +
            "// GENERATED by tools/src/projection/providers/node/structural-projection-provider.ts — do not hand-edit.\n" +
            `export type ${definition.typeName} = ${definition.values.map((value) => encodedLiteral("node", value)).join(" | ")};\n`;
    }
    return renderObject(definition.typeName, definition);
}
export class NodeStructuralProjectionProvider {
    target = "node";
    render(graph, profile) {
        if (graph.target !== this.target || profile.language !== this.target)
            throw new Error("Node renderer received another target.");
        const files = graph.definitions.map((definition) => projectionFile(`${kebabCase(definition.typeName)}.ts`, renderDefinition(definition), definition));
        const index = graph.definitions.map((definition) => `export * from "./${kebabCase(definition.typeName)}.js";`).join("\n") + "\n";
        files.push({
            relativePath: "index.ts",
            content: index,
            digest: sha256(index),
            sourcePointers: graph.definitions.map((definition) => definition.sourcePointer)
        });
        return {
            planType: "projection-plan.v1",
            target: this.target,
            outputDirectory: profile.outputDirectory,
            files
        };
    }
}
